create table if not exists public.bot_configs (id bigint generated by default as identity primary key,user_id uuid not null unique references auth.users(id) on delete cascade,enabled boolean not null default false,strategy text not null default 'sma' check(strategy in ('sma','rsi')),symbol text not null default 'SPY',risk_pct numeric not null default 1,stop_loss_pct numeric not null default 2,take_profit_pct numeric not null default 4,daily_loss_pct numeric not null default 3,updated_at timestamptz not null default now());
create table if not exists public.trade_logs (id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,symbol text not null,strategy text not null,status text not null,result jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.bot_configs enable row level security;alter table public.trade_logs enable row level security;
create policy "own config read" on public.bot_configs for select using(auth.uid()=user_id);create policy "own config insert" on public.bot_configs for insert with check(auth.uid()=user_id);create policy "own config update" on public.bot_configs for update using(auth.uid()=user_id);create policy "own logs read" on public.trade_logs for select using(auth.uid()=user_id);
create index if not exists trade_logs_user_created on public.trade_logs(user_id,created_at desc);
